<section id="report-closings" class="report-panel hidden"><div class="users-heading"><div><h2>Historique des clôtures</h2><p>Totaux figés par véhicule.</p></div></div><div class="report-card-grid"><?php foreach($clotures as$c):?><article><i class="bi bi-lock-fill"></i><div><strong>#<?= (int)$c['id'] ?> · <?= htmlspecialchars($c['immatriculation']) ?></strong><small><?= date('d/m/Y H:i',strtotime($c['created_at'])) ?> · <?= (int)$c['nombre_recettes'] ?> recette(s), <?= (int)$c['nombre_depenses'] ?> dépense(s), <?= (int)$c['nombre_remunerations'] ?> rémunération(s)</small></div><b><?= $fmt($c['total_recettes_usd']-$c['total_depenses_usd'],'USD') ?> USD<br><?= $fmt($c['total_recettes_cdf']-$c['total_depenses_cdf'],'CDF') ?> CDF</b></article><?php endforeach;?><?php if(!$clotures):?><p class="report-empty">Aucune clôture.</p><?php endif;?></div></section>
</div><footer class="dashboard-footer">© <?= date('Y') ?> MWIRA Trans <span>Rapports de gestion</span></footer></main></div><script>function switchReport(v){document.querySelectorAll('.report-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));document.querySelectorAll('.report-panel').forEach(p=>p.classList.toggle('hidden',p.id!=='report-'+v))}function toggleSidebar(){document.getElementById('dashboard-sidebar').classList.toggle('open');document.getElementById('mobile-overlay').classList.toggle('show')}</script></body></html>
